const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const aoi = ee.FeatureCollection("FAO/GAUL/2015/level0").filter(ee.Filter.eq('ADM0_NAME', 'Brazil')).geometry();
  const year1 = 2003;
  const year2 = 2019;

  // 2. Data Acquisition & Check
  const collection = ee.ImageCollection('MODIS/006/MCD12Q1');

  const image1 = collection.filter(ee.Filter.date(`${year1}-01-01`, `${year1}-12-31`)).first();
  const image2 = collection.filter(ee.Filter.date(`${year2}-01-01`, `${year2}-12-31`)).first();

  if (!image1.getInfo() || !image2.getInfo()) {
    console.log('Evidence: Could not retrieve images for one or both years.');
    console.log('C1');
    return;
  }

  const landcoverBand = 'LC_Type1';
  // IGBP classification: 12 = Croplands, 14 = Cropland/Natural Vegetation Mosaics
  const croplandCodes = [12, 14];

  // 3. Processing
  const cropland1 = image1.select(landcoverBand).remap(croplandCodes, ee.List.repeat(1, croplandCodes.length), 0);
  const cropland2 = image2.select(landcoverBand).remap(croplandCodes, ee.List.repeat(1, croplandCodes.length), 0);

  const areaImage = ee.Image.pixelArea().divide(1e6); // Area in sq km

  const area1Image = cropland1.multiply(areaImage);
  const area2Image = cropland2.multiply(areaImage);

  const scale = 5000; // Use a coarse scale for a country-level statistic to avoid timeout

  // 4. Calculation
  const stats1 = area1Image.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e12
  });

  const stats2 = area2Image.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e12
  });

  const area1 = ee.Number(stats1.get(landcoverBand)).getInfo();
  const area2 = ee.Number(stats2.get(landcoverBand)).getInfo();

  // 5. Validation & Final Answer
  if (area1 === null || area2 === null || area1 === undefined || area2 === undefined) {
    console.log(`Evidence: Failed to calculate area. Year ${year1}: ${area1}, Year ${year2}: ${area2}`);
    console.log('C3');
    return;
  }

  if (area1 === 0 || area2 === 0) {
      console.log(`Evidence: Calculation resulted in zero area for one or both years.`);
      console.log(`Evidence: ${year1} Cropland Area (sq km): ${area1.toFixed(0)}`);
      console.log(`Evidence: ${year2} Cropland Area (sq km): ${area2.toFixed(0)}`);
      console.log('C2');
      return;
  }

  console.log(`Evidence: ${year1} Cropland Area (sq km): ${area1.toFixed(0)}`);
  console.log(`Evidence: ${year2} Cropland Area (sq km): ${area2.toFixed(0)}`);

  if (area2 > area1) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error('An error occurred during the analysis.');
    console.error(err);
    console.log('D');
});
